test('iframe booking form submission', async ({ page }) => {
  await page.goto('/demo-embed');
  const frame = page.frameLocator('#befer-booking-iframe');
  await frame.getByLabel('Service').selectOption('Consultation');
  await frame.getByRole('button', { name: /confirm time/i }).click();
  await expect(frame.getByText('Slot reserved')).toBeVisible();
});
